
/* ====== MENÚ MÓVIL ====== */
const nav=document.getElementById("navMenu");
const ham=document.getElementById("hamburgerBtn");
if (nav && ham) {
  ham.addEventListener("click",()=>nav.classList.toggle("active"));
  document.addEventListener("click",e=>{
    if(!nav.contains(e.target)&&!ham.contains(e.target))nav.classList.remove("active");
  });
}

/* ====== HEADER SCROLL ====== */
window.addEventListener("scroll",()=>{
  const header=document.querySelector(".header");
  if(header) header.classList.toggle("scrolled",window.scrollY>100);
});

/* ====== ANIMACIONES ====== */
const obs=new IntersectionObserver(entries=>{
 entries.forEach(e=>{
  if(e.isIntersecting){
   e.target.classList.add("visible");
   obs.unobserve(e.target);
  }
 });
},{threshold:.2});
document.querySelectorAll("[data-animate]").forEach(el=>obs.observe(el));

/* ====== FOOTER DINÁMICO ====== */
const initializeFooterObserver = (footer)=>{
 if(!footer) return;
 const footerObserver=new IntersectionObserver(entries=>{
  entries.forEach(e=>{
   if(e.isIntersecting){
    footer.classList.add("visible");
   }
  });
 },{threshold:.3});
 footerObserver.observe(footer);
};

const footerPlaceholder=document.getElementById("footer-placeholder");
if(footerPlaceholder){
 fetch("modules/footer.html")
  .then(response=>{
    if(!response.ok) throw new Error(`No se pudo cargar el footer: ${response.status}`);
    return response.text();
  })
  .then(html=>{
    footerPlaceholder.innerHTML=html;
    const footerEl=footerPlaceholder.querySelector(".footer");
    initializeFooterObserver(footerEl);
  })
  .catch(error=>{console.error(error);});
} else {
 const footer=document.querySelector("footer");
 initializeFooterObserver(footer);
}

/* ====== SCROLL SUAVE ====== */
document.querySelectorAll('a[href^="#"]').forEach(a=>{
 a.addEventListener("click",function(e){
  const id=this.getAttribute("href");
  if(id.length>1){
   e.preventDefault();
   document.querySelector(id)?.scrollIntoView({behavior:"smooth"});
  }
 });
});
